import { chmodSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import { privateKeyToAccount } from 'viem/accounts';
import { getRefundEnv } from '../config/env';
import type { Rail, KeyState } from './refund-payout.core';

/**
 * T-0553 refund key custody. The refund keys are generated by scripts/server-wallet-init.sh
 * (never by this code) and live only in the .env of the host. This module derives the ADDRESS,
 * compares it with the record file (key-mismatch guard) and hands the key to the signer port.
 * It never logs, returns in a health payload or serializes a key.
 */

const KEY_RE = /^0x[0-9a-fA-F]{64}$/;
export const ENV_NAME: Record<Rail, 'REFUND_SIGNER_KEY_BASE' | 'REFUND_SIGNER_KEY_TEMPO'> = {
  base: 'REFUND_SIGNER_KEY_BASE',
  tempo: 'REFUND_SIGNER_KEY_TEMPO',
};

export interface RailKey {
  rail: Rail;
  state: KeyState;
  /** Why the state is not ok (never contains key material). */
  reason?: string;
  address: string | null;
}

interface RecordEntry {
  name: string;
  rail: string;
  address: string;
  created_at: string;
}

export interface KeyEnv {
  source?: NodeJS.ProcessEnv;
  /** Addresses the refund wallet must differ from (operator gas wallet, revenue wallet). */
  forbidden: Array<string | null | undefined>;
  log?: (level: 'info' | 'warn' | 'error', msg: string, extra?: Record<string, unknown>) => void;
  now?: () => Date;
}

function readRecord(path: string): RecordEntry[] | 'unreadable' {
  if (!existsSync(path)) return [];
  try {
    const v = JSON.parse(readFileSync(path, 'utf8') || '[]');
    return Array.isArray(v) ? (v as RecordEntry[]) : 'unreadable';
  } catch {
    return 'unreadable';
  }
}

const warned = new Set<string>();

/** Evaluate both rails. May write the record on the first boot after the init script ran. */
export function evaluateKeys(env: KeyEnv): Record<Rail, RailKey> {
  const src = env.source ?? process.env;
  const cfg = getRefundEnv(src);
  const log = env.log ?? (() => undefined);
  const forbidden = env.forbidden.filter((x): x is string => !!x).map((x) => x.toLowerCase());
  const out = {} as Record<Rail, RailKey>;
  for (const rail of ['base', 'tempo'] as const) {
    const name = ENV_NAME[rail];
    const key = cfg[name];
    const rec = readRecord(cfg.REFUND_WALLET_RECORD);
    const entry = rec === 'unreadable' ? undefined : rec.find((e) => e.name === name);
    const once = (msg: string) => {
      if (!warned.has(`${rail}:${msg}`)) {
        warned.add(`${rail}:${msg}`);
        log('warn', msg);
      }
    };
    if (rec === 'unreadable') {
      out[rail] = { rail, state: 'mismatch', reason: 'record_unreadable', address: null };
      continue;
    }
    if (!key) {
      if (entry) {
        out[rail] = {
          rail,
          state: 'mismatch',
          reason: 'key_absent_record_present',
          address: entry.address,
        };
      } else {
        once(`refund wallet ${rail}: no key, payouts off`);
        out[rail] = { rail, state: 'missing', address: null };
      }
      continue;
    }
    if (!KEY_RE.test(key)) {
      out[rail] = {
        rail,
        state: 'mismatch',
        reason: 'key_malformed',
        address: entry?.address ?? null,
      };
      continue;
    }
    const address = privateKeyToAccount(key as `0x${string}`).address;
    if (!entry) {
      try {
        const next = [
          ...rec,
          { name, rail, address, created_at: (env.now?.() ?? new Date()).toISOString() },
        ];
        writeFileSync(cfg.REFUND_WALLET_RECORD, JSON.stringify(next, null, 2) + '\n', {
          mode: 0o600,
        });
        chmodSync(cfg.REFUND_WALLET_RECORD, 0o600);
      } catch {
        out[rail] = { rail, state: 'mismatch', reason: 'record_unwritable', address };
        continue;
      }
    } else if (entry.address.toLowerCase() !== address.toLowerCase()) {
      out[rail] = { rail, state: 'mismatch', reason: 'address_differs_from_record', address };
      continue;
    }
    if (forbidden.includes(address.toLowerCase())) {
      out[rail] = {
        rail,
        state: 'mismatch',
        reason: 'address_equals_operator_or_revenue',
        address,
      };
      continue;
    }
    out[rail] = { rail, state: 'ok', address };
  }
  return out;
}

/** The raw key for a rail, for the signer port only. Empty string when absent. */
export function refundSignerKey(
  rail: Rail,
  source: NodeJS.ProcessEnv = process.env,
): `0x${string}` {
  return getRefundEnv(source)[ENV_NAME[rail]] as `0x${string}`;
}

/** Test helper: forget the once-per-process log memo. */
export function resetKeyLogMemo(): void {
  warned.clear();
}
